/**
 *
 * RatingOff is the base/empty icon layer of a Rating star.
 * It is always fully visible and serves as the visual base for the option.
 *
 * [Live Demo](https://www.primereact.org/rating/)
 *
 * @module RatingOff
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { RatingRootInstance } from './RatingRoot.types';
/**
 * Defines passthrough(pt) options type in RatingOff component.
 */
export type RatingOffPassThroughType<E> = PassThroughType<RatingOffInstance, E>;
/**
 * Defines passthrough(pt) options of RatingOff component.
 */
export interface RatingOffPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: RatingOffPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in RatingOff component.
 */
export interface RatingOffProps extends BaseComponentProps<RatingOffInstance, unknown, RatingOffPassThrough> {
}
/**
 * Defines valid state in RatingOff component.
 */
export interface RatingOffState {
}
/**
 * Defines the methods and properties exposed by RatingOff component.
 */
export interface RatingOffExposes {
    /**
     * The parent Rating component instance.
     */
    rating: RatingRootInstance | undefined | null;
    /**
     * The parent RatingOption component instance.
     */
    ratingOption: import('./RatingOption.types').RatingOptionInstance | undefined | null;
}
/**
 * Instance of RatingOff component.
 */
export type RatingOffInstance = ComponentInstance<RatingOffProps, RatingOffState, RatingOffExposes>;
